class Solution:
    def smallestString(self, s: str) -> str:
        t = list(s)
        n = len(t)
        i = 0
        while i < n and t[i] == 'a':
            i += 1
        if i == n:
            t[n - 1] = 'z'
        else:
            while i < n and t[i] != 'a':
                t[i] = chr(ord(t[i]) - 1)
                i += 1
        return ''.join(t)

