public String smallestString(String s) {
    char[] t = s.toCharArray();
    int i = 0, n = t.length;
    while (i < n && t[i] == 'a') i++;
    if (i == n) t[n - 1] = 'z';
    else while (i < n && t[i] != 'a') { t[i]--; i++; }
    return new String(t);
}

