var smallestString = function(s) {
    const t = s.split('');
    let i = 0;
    const n = t.length;
    while (i < n && t[i] === 'a') i++;
    if (i === n) t[n - 1] = 'z';
    else while (i < n && t[i] !== 'a') {
        t[i] = String.fromCharCode(t[i].charCodeAt(0) - 1);
        i++;
    }
    return t.join('');
};
